// Compares Wan2.1's host UniPC and CFG (`src/wan/scheduler.ts`) with a fixture baked by driving the
// real classes of diffusers 0.39.0. Pure-function tests that need neither a GPU nor real weights.
//
// The fixture is `fixtures/wan-scheduler/` (generated by tools/export-recipes/wan/scheduler_ref.py — the
// expected values are the outputs of upstream's `UniPCMultistepScheduler.set_timesteps` / `step` and of
// the CFG formula of `pipeline_wan.py`, not a copy of the formulas).
//
// - σ sequence: **bit-exact** (Uint32). The intermediate f64 sequence also matches the JSON values exactly
//   (computed in f64 → f32 at the end — decision 5).
// - timestep sequence: exact match (the first is 999 — including the 1e-6 correction of σ[0]).
// - trajectory (a fixed sequence of 50 model outputs): atol (measured in the doc of {@link TRAJECTORY_ATOL}).
// - CFG: **bit-exact**.
//
// The fault injections split across two checks. Faults that show in the σ sequence (dropping the σ[0]
// correction, shifting the σ sequence by one, shift 5.0) are caught by the bit-exact σ / timestep check,
// and faults of the update rule (bh2 → bh1, dropping to first order, swapping the step order) by the
// trajectory's atol check.

import { readFile, readTextFile } from "@karume/test-support/fs";
import { test } from "vite-plus/test";
import { assert, assertEquals, assertThrows } from "@std/assert";
import { parseSafetensors, type SafetensorsFile } from "@karume/runtime";
import {
  flowShiftedSigmas,
  WAN_UNIPC_CONFIG,
  wanClassifierFreeGuidance,
  type WanUniPcConfig,
  WanUniPcSampler,
  wanUniPcSchedule,
} from "../src/wan/scheduler.ts";

/**
 * The tolerance (absolute) of the trajectory (50 steps, latent `[16,3,16,16]`) between TS and upstream
 * (torch CPU f32).
 *
 * Measured (2026-10-02, a plain comparison with `atol = rtol = 0`): max absolute difference **3.815e-6**
 * (step 38, reference max absolute value 4.29). 364,883 of 614,400 elements differ, and steps 0..3 are
 * bit-exact.
 *
 * The difference comes from 1 ULP of the f32 `log`: upstream's `torch.log` on a 0-d tensor (MKL's VML)
 * and `Math.log` rounded to f32 (correctly rounded) differ by 1 ULP for 6 of the 50 σ values (`log(1 − σ)`
 * or `log(σ)` at steps 19 / 21 / 23 / 32 / 42 / 43), which propagates through λ → h → the `expm1`
 * coefficients (confirmed by comparing the coefficients in hex). It is not a formula mix-up — everything
 * other than the diverging coefficients is bit-exact.
 *
 * atol 2e-5 is about 5.2 times the measured worst case (decision 8's "about 5 times the measured worst
 * case").
 */
const TRAJECTORY_ATOL = 2e-5;

/**
 * The factor (lower bound) by which the update-rule fault injections must stay away from the band.
 *
 * The guideline of ADR 0118 acceptance step 6 (Anima's precedent) is 1e4 times, but on a trajectory of
 * 50 steps with random model outputs the measurements were 2.0e3..1.05e4 times (bh1 7.96e3, first order
 * 1.05e4, swapping steps 0 / 1 2.04e3, swapping steps 10 / 11 4.71e3 — 2026-10-02). The band (5 times the
 * measured worst case) stays put, and the check is set at 1e3 times, below the smallest observation
 * (disclosed). For bh1 it is the difference of the finite elements (the last step is NaN, as upstream —
 * see the note on the fault injection below).
 *
 * The faults that show in the σ sequence (the σ[0] correction, shifting by one, shift 5.0) give
 * 1.5e-3..2.7e-1 on the trajectory (77..1.35e4 times atol), and the bit-exact σ / timestep side holds
 * their check (the σ[0] correction moves the input that max acts on by only 1e-6, so the trajectory's
 * atol gives no margin for it).
 */
const UPDATE_FAULT_MARGIN = 1e3;

const FIXTURE_DIR = new URL("./fixtures/wan-scheduler/", import.meta.url);

type Schedule = {
  readonly steps: number;
  readonly sigmas_f64: readonly number[];
  readonly sigmas_f32: readonly number[];
  readonly timesteps: readonly number[];
};

type Meta = {
  readonly scheduler_config: {
    readonly num_train_timesteps: number;
    readonly solver_order: number;
    readonly solver_type: string;
    readonly flow_shift: number;
    readonly prediction_type: string;
    readonly predict_x0: boolean;
    readonly lower_order_final: boolean;
    readonly final_sigmas_type: string;
    readonly use_flow_sigmas: boolean;
    readonly use_dynamic_shifting: boolean;
    readonly thresholding: boolean;
    readonly disable_corrector: readonly number[];
  };
  readonly latent_shape: readonly number[];
  readonly guidance_scale: number;
  readonly orders: readonly number[];
  readonly correctors: readonly boolean[];
  readonly schedules: Readonly<Record<string, Schedule>>;
};

const meta = JSON.parse(await readTextFile(new URL("unipc.json", FIXTURE_DIR))) as Meta;
const fixture: SafetensorsFile = await (async () => {
  const bytes = await readFile(new URL("unipc.safetensors", FIXTURE_DIR));
  return parseSafetensors(
    bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer,
  );
})();

const floats = (key: string): Float32Array<ArrayBuffer> => {
  const view = fixture.tensors.get(key);
  if (view === undefined || view.dtype !== "F32") throw new Error(`fixture '${key}' is not F32`);
  return new Float32Array(fixture.buffer, view.byteOffset, view.byteLength / 4);
};

const bitsOf = (values: Float32Array): Uint32Array =>
  new Uint32Array(values.buffer, values.byteOffset, values.length);

const SHIFT = meta.scheduler_config.flow_shift;
const STEPS = 50;
const ELEMENTS = meta.latent_shape.reduce((count, dim) => count * dim, 1);

/** Runs upstream's trajectory loop (`for t in timesteps: latents = step(out[i], t, latents)`) in TS. */
const runTrajectory = (
  sigmas: Float32Array<ArrayBuffer>,
  config: WanUniPcConfig = WAN_UNIPC_CONFIG,
  order: readonly number[] = [...Array(STEPS).keys()],
): Float32Array[] => {
  const outputs = floats("model_outputs");
  const sampler = new WanUniPcSampler({ sigmas }, config);
  let latents: Float32Array<ArrayBuffer> = floats("latents_init").slice();
  const states: Float32Array[] = [];
  for (const step of order) {
    latents = sampler.step(outputs.subarray(step * ELEMENTS, (step + 1) * ELEMENTS), latents);
    states.push(latents);
  }
  return states;
};

/**
 * The difference over the whole trajectory (against the fixture's `trajectory`): the max absolute
 * difference between finite elements, and the number of non-finite elements.
 *
 * MUST: keep non-finite values out of the maximum — `Math.max` returns NaN, and the comparison check
 * would fall on the "does not exceed" side.
 */
const trajectoryDifference = (
  states: readonly Float32Array[],
): { readonly maxAbs: number; readonly nonFinite: number } => {
  const trajectory = floats("trajectory");
  let maxAbs = 0;
  let nonFinite = 0;
  states.forEach((state, step) => {
    const want = trajectory.subarray(step * ELEMENTS, (step + 1) * ELEMENTS);
    for (let element = 0; element < ELEMENTS; element += 1) {
      if (!Number.isFinite(state[element])) {
        nonFinite += 1;
        continue;
      }
      maxAbs = Math.max(maxAbs, Math.abs(state[element] - want[element]));
    }
  });
  return { maxAbs, nonFinite };
};

test("UniPC: the fixture's scheduler config is the branch this port targets (flow, bh2, second order, x0 prediction)", () => {
  const config = meta.scheduler_config;
  assertEquals(
    {
      numTrainTimesteps: config.num_train_timesteps,
      solverOrder: config.solver_order,
      solverType: config.solver_type,
    },
    { ...WAN_UNIPC_CONFIG },
  );
  assertEquals(
    [
      config.prediction_type,
      config.predict_x0,
      config.lower_order_final,
      config.final_sigmas_type,
      config.use_flow_sigmas,
      config.use_dynamic_shifting,
      config.thresholding,
      config.disable_corrector.length,
    ],
    ["flow_prediction", true, true, "zero", true, false, false, 0],
  );
  assertEquals(SHIFT, 3);
});

for (const steps of [2, STEPS]) {
  test(`UniPC: the σ sequence of ${steps} steps is bit-exact with upstream, and the timesteps match exactly`, () => {
    const expected = meta.schedules[String(steps)];
    const schedule = wanUniPcSchedule(steps, SHIFT, WAN_UNIPC_CONFIG.numTrainTimesteps);
    assertEquals([...bitsOf(schedule.sigmas)], [...bitsOf(Float32Array.from(expected.sigmas_f32))]);
    assertEquals(schedule.timesteps, expected.timesteps);
    assertEquals(
      schedule.timesteps[0],
      999,
      "the first timestep is 999 through the 1e-6 correction of σ[0]",
    );
    // The intermediate f64 sequence (with the correction and the final 0 appended) also matches
    // upstream's numpy formula exactly.
    const sigmas64 = flowShiftedSigmas(steps, SHIFT, WAN_UNIPC_CONFIG.numTrainTimesteps);
    sigmas64[0] -= 1e-6;
    assertEquals([...sigmas64, 0], expected.sigmas_f64);
  });
}

test("UniPC: the σ sequence and the timesteps also match the F32 / I64 sequences in the safetensors (a second source besides the JSON)", () => {
  const schedule = wanUniPcSchedule(STEPS, SHIFT, WAN_UNIPC_CONFIG.numTrainTimesteps);
  assertEquals([...bitsOf(schedule.sigmas)], [...bitsOf(floats("sigmas"))]);
  const view = fixture.tensors.get("timesteps");
  assert(view !== undefined && view.dtype === "I64", "the fixture's timesteps are not I64");
  const timesteps = new BigInt64Array(fixture.buffer, view.byteOffset, view.byteLength / 8);
  assertEquals(schedule.timesteps, [...timesteps].map(Number));
});

test("UniPC: the trajectory over a fixed sequence of model outputs is within atol of upstream's step (order 1 → 2 → 1, corrector from the 2nd step)", () => {
  // That the orders and the presence of the corrector have the same form as upstream's record is
  // checked first in the fixture's metadata (the precondition of the numeric check).
  assertEquals(meta.orders, [1, ...Array(STEPS - 2).fill(2), 1]);
  assertEquals(meta.correctors, [false, ...Array(STEPS - 1).fill(true)]);
  const schedule = wanUniPcSchedule(STEPS, SHIFT, WAN_UNIPC_CONFIG.numTrainTimesteps);
  const states = runTrajectory(schedule.sigmas);
  const { maxAbs, nonFinite } = trajectoryDifference(states);
  assertEquals(nonFinite, 0, "non-finite");
  console.log(`[wan-scheduler] trajectory maxAbs=${maxAbs}（atol ${TRAJECTORY_ATOL}）`);
  assert(
    maxAbs <= TRAJECTORY_ATOL,
    `the trajectory's max absolute difference ${maxAbs} is outside atol ${TRAJECTORY_ATOL}`,
  );
  // The first 4 steps are bit-exact because the 1-ULP coefficients do not show yet (a positive control
  // that atol is not hiding slack).
  const trajectory = floats("trajectory");
  for (let step = 0; step < 4; step += 1) {
    assertEquals(
      [...bitsOf(states[step])],
      [...bitsOf(trajectory.subarray(step * ELEMENTS, (step + 1) * ELEMENTS))],
      `step ${step}`,
    );
  }
});

test("UniPC fault injection (the σ-sequence check): dropping the σ[0] correction, shifting the σ sequence by one and shift 5.0 break the σ / timestep match", () => {
  const expected = meta.schedules[String(STEPS)];
  const want = [...bitsOf(Float32Array.from(expected.sigmas_f32))];
  const noEpsilon = Float32Array.from([
    ...flowShiftedSigmas(STEPS, SHIFT, WAN_UNIPC_CONFIG.numTrainTimesteps),
    0,
  ]);
  const faults: readonly { readonly label: string; readonly sigmas: Float32Array<ArrayBuffer> }[] =
    [
      { label: "drop the 1e-6 correction of σ[0]", sigmas: noEpsilon },
      {
        label: "shift the σ sequence by one (from the 2nd entry of the 51-step sequence)",
        sigmas: wanUniPcSchedule(STEPS + 1, SHIFT, WAN_UNIPC_CONFIG.numTrainTimesteps).sigmas.slice(
          1,
        ),
      },
      {
        label: "shift 5.0",
        sigmas: wanUniPcSchedule(STEPS, 5, WAN_UNIPC_CONFIG.numTrainTimesteps).sigmas,
      },
    ];
  for (const { label, sigmas } of faults) {
    assertEquals(sigmas.length, want.length, label);
    const mismatched = [...bitsOf(sigmas)].filter((bits, index) => bits !== want[index]).length;
    // How much it affects the trajectory is only recorded (σ-sequence faults are caught by the σ check
    // — top of the file).
    console.log(
      `[wan-scheduler] fault ${label}: σ mismatches ${mismatched}, trajectory maxAbs=${
        trajectoryDifference(runTrajectory(sigmas)).maxAbs
      }`,
    );
    assert(mismatched > 0, `${label}: the σ sequence was bit-exact with upstream`);
  }
  // The σ[0] correction is also caught by the timestep check (1000 without the correction).
  assertEquals(Math.trunc(noEpsilon[0] * WAN_UNIPC_CONFIG.numTrainTimesteps), 1000);
  assertEquals(expected.timesteps[0], 999);
});

test("UniPC fault injection (the trajectory check): bh2 → bh1, dropping to first order and swapping the step order land outside atol", () => {
  const sigmas = wanUniPcSchedule(STEPS, SHIFT, WAN_UNIPC_CONFIG.numTrainTimesteps).sigmas;
  const swapped = (a: number, b: number): number[] => {
    const order = [...Array(STEPS).keys()];
    [order[a], order[b]] = [order[b], order[a]];
    return order;
  };
  const faults: readonly { readonly label: string; readonly states: () => Float32Array[] }[] = [
    {
      label: "bh2 → bh1",
      states: () => runTrajectory(sigmas, { ...WAN_UNIPC_CONFIG, solverType: "bh1" }),
    },
    {
      label: "drop to first order",
      states: () => runTrajectory(sigmas, { ...WAN_UNIPC_CONFIG, solverOrder: 1 }),
    },
    {
      label: "swap the model outputs of steps 0 / 1",
      states: () => runTrajectory(sigmas, WAN_UNIPC_CONFIG, swapped(0, 1)),
    },
    {
      label: "swap the model outputs of steps 10 / 11",
      states: () => runTrajectory(sigmas, WAN_UNIPC_CONFIG, swapped(10, 11)),
    },
  ];
  for (const { label, states } of faults) {
    // bh1 becomes NaN at the last step (σ = 0 gives h = ∞, `B(h) = hh = −∞`) through `−∞ × 0`, as
    // upstream does (upstream's `x_t_ − alpha_t·B_h·0`). The check looks at the difference of the
    // finite elements.
    const { maxAbs, nonFinite } = trajectoryDifference(states());
    console.log(
      `[wan-scheduler] fault ${label}: maxAbs=${maxAbs} (${(maxAbs / TRAJECTORY_ATOL).toExponential(
        2,
      )} times atol), non-finite ${nonFinite}`,
    );
    assert(
      maxAbs > UPDATE_FAULT_MARGIN * TRAJECTORY_ATOL,
      `${label}: the max absolute difference ${maxAbs} does not exceed ${UPDATE_FAULT_MARGIN} times atol`,
    );
  }
});

test("UniPC: a step outside the σ sequence and inputs of mismatched length fail loudly", () => {
  const schedule = wanUniPcSchedule(1, SHIFT, WAN_UNIPC_CONFIG.numTrainTimesteps);
  assertEquals(schedule.timesteps, [999]);
  const sampler = new WanUniPcSampler(schedule, WAN_UNIPC_CONFIG);
  assertThrows(
    () => sampler.step(new Float32Array(3), new Float32Array(4)),
    RangeError,
    "elements",
  );
  const once = sampler.step(new Float32Array([1, -1]), new Float32Array([0.5, 0.25]));
  // One step (σ: 0.999999 → 0) at first order is the x0 prediction itself: x0 = x − σ·v.
  assertEquals(
    [...once],
    [Math.fround(0.5 - schedule.sigmas[0]), Math.fround(0.25 + schedule.sigmas[0])],
  );
  assertThrows(
    () => sampler.step(new Float32Array(2), new Float32Array(2)),
    RangeError,
    "σ sequence",
  );
  assertThrows(() => wanUniPcSchedule(0, SHIFT, 1000), RangeError, "steps");
  assertThrows(() => wanUniPcSchedule(2, 0, 1000), RangeError, "shift");
  assertThrows(() => wanUniPcSchedule(2, Number.NaN, 1000), RangeError, "shift");
});

test("UniPC: the steps limit is num_train_timesteps (exactly is accepted; past it fails before the σ sequence is built)", () => {
  // Integer timesteps trunc(σ·N) take only N values 0..N−1, so steps past N always repeat.
  const limit = WAN_UNIPC_CONFIG.numTrainTimesteps;
  const schedule = wanUniPcSchedule(limit, SHIFT, limit);
  assertEquals(schedule.timesteps.length, limit, "exactly the limit is inside the boundary");
  assertThrows(() => wanUniPcSchedule(limit + 1, SHIFT, limit), RangeError, "steps");
  // Fails before allocating the array: allocating would mean a synchronous loop over several GiB, and
  // this line would never return.
  assertThrows(() => wanUniPcSchedule(Number.MAX_SAFE_INTEGER, SHIFT, limit), RangeError, "steps");
});

test("CFG: uncond + g·(cond − uncond) is bit-exact with upstream's formula (guide 5.0)", () => {
  assertEquals(meta.guidance_scale, 5);
  const got = wanClassifierFreeGuidance(
    floats("cfg.cond"),
    floats("cfg.uncond"),
    meta.guidance_scale,
  );
  assertEquals([...bitsOf(got)], [...bitsOf(floats("cfg.out"))]);
  // Fault injection on the operation order: changing it to `cond·g + uncond·(1 − g)` breaks the last
  // bit (the order of the formula is pinned by the check).
  const cond = floats("cfg.cond");
  const uncond = floats("cfg.uncond");
  const reordered = cond.map((value, index) =>
    Math.fround(Math.fround(value * 5) + Math.fround(uncond[index] * -4)),
  );
  assert(
    bitsOf(reordered).some((bits, index) => bits !== bitsOf(got)[index]),
    "bit-exact even with the operation order changed (the check does not pin the order of the formula)",
  );
  assertThrows(
    () => wanClassifierFreeGuidance(new Float32Array(2), new Float32Array(3), 5),
    RangeError,
  );
});
